mapper.select:
SELECT id, school_id, oauth_user_id, role, status, joined_at, invited_by_oauth_user_id
FROM school_users
WHERE school_id = #{schoolId}
  AND oauth_user_id = #{oauthUserId}
LIMIT 1

mapper.update:
UPDATE school_users
SET role = #{role}
WHERE school_id = #{schoolId}
  AND oauth_user_id = #{oauthUserId}

mapper.delete:
DELETE FROM school_users
WHERE school_id = #{schoolId}
  AND oauth_user_id = #{oauthUserId}
